if (c->is_infinite()) {
    return Vector(0.0, 0.0, 0.0);
}

// collect lifted points of the four vertices
LiftedPoint lp[4];
for (int i = 0; i < 4; ++i) {
    const auto& wp = c->vertex(i)->point();          // Weighted_point
    const auto& p  = wp.point();                    // Bare_point
    double x = CGAL::to_double(p.x());
    double y = CGAL::to_double(p.y());
    double z = CGAL::to_double(p.z());
    double w = CGAL::to_double(wp.weight());
    lp[i] = lifted_point(x, y, z, w);
}

// hyperplane through the lifted points
HyperPlane hp(lp[0], lp[1], lp[2], lp[3]);

// normal vector of the hyperplane (4‑D)
auto n = hp.orthogonal_vector();
double a0 = n[0];
double a1 = n[1];
double a2 = n[2];
double a3 = n[3];

// avoid division by zero or degenerate cases
const double eps = std::numeric_limits<double>::epsilon();
if (std::abs(a3) < eps || !std::isfinite(a3)) {
    return Vector(0.0, 0.0, 0.0);
}

// velocity is - (a0, a1, a2) / (2 * a3)
double factor = -0.5 / a3;
return Vector(a0 * factor, a1 * factor, a2 * factor);

